module barrel_shifter(
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);
// Internal wires for mux outputs
wire [7:0] mux_stage0_out;
wire [7:0] mux_stage1_out;
wire [7:0] mux_stage2_out;
// Stage 0: Shift by 4 positions
assign mux_stage0_out = (ctrl[2]) ? {in[3:0], in[7:4]} : in;
// Stage 1: Shift by 2 positions
assign mux_stage1_out = (ctrl[1]) ? {mux_stage0_out[5:0], mux_stage0_out[7:6]} : mux_stage0_out;
// Stage 2: Shift by 1 position
assign mux_stage2_out = (ctrl[0]) ? {mux_stage1_out[6:0], mux_stage1_out[7]} : mux_stage1_out;
// Output assignment
assign out = mux_stage2_out;
endmodule
